    script?.video_title ||
    script?.scenes?.[0]?.caption ||
    report?.report_title ||
    'shorts';

  const cleanTitle = String(title)
    .replace(/[^0-9A-Za-z가-힣 _-]/g, '')
    .trim()
    .replace(/\s+/g, '_');

  return (
    $now.setZone('Asia/Seoul').toFormat('yyyyMMdd')
    + '_'
    + cleanTitle
    + '.mp4'
  );
})()
}}

