const MAX_CHARS = 13;
const MAX_GAP = 0.38;

const items = $input.all();


function toSrtTime(seconds) {

  const ms = Math.max(
    0,
    Math.round(seconds * 1000)
  );

  const h =
    String(
      Math.floor(ms / 3600000)
    ).padStart(2, '0');

  const m =
    String(
      Math.floor(
        (ms % 3600000) / 60000
      )
    ).padStart(2, '0');

  const s =
    String(
      Math.floor(
        (ms % 60000) / 1000
      )
    ).padStart(2, '0');

  const milli =
    String(
      ms % 1000
    ).padStart(3, '0');

  return `${h}:${m}:${s},${milli}`;
}


function makeChunks(words) {

  const chunks = [];
  let currentWords = [];

  for (let i = 0; i < words.length; i++) {

    const word = words[i];

    if (
      !word ||
      typeof word.text !== 'string' ||
      typeof word.start !== 'number' ||
      typeof word.end !== 'number'
    ) {
      continue;
    }


    if (currentWords.length === 0) {

      currentWords.push(word);

      continue;
    }


    const previousWord =
      currentWords[
        currentWords.length - 1
      ];


    const candidateWords = [
      ...currentWords,
      word
    ];


    const candidateText =
      candidateWords
        .map(w => w.text)
        .join(' ');


    const candidateLength =
      candidateText
        .replace(/\s/g, '')
        .length;


    const gap =
      word.start -
      previousWord.end;


    const previousEndsSentence =
      /[.!?。！？]$/.test(
        previousWord.text
      );


    if (
      candidateLength > MAX_CHARS ||
      gap > MAX_GAP ||
      previousEndsSentence
    ) {

      chunks.push({
        text:
          currentWords
            .map(w => w.text)
            .join(' '),

        start:
          currentWords[0].start,

        end:
          currentWords[
            currentWords.length - 1
          ].end
      });


      currentWords = [word];

    } else {

      currentWords.push(word);
    }
  }


  if (currentWords.length > 0) {

    chunks.push({

      text:
        currentWords
          .map(w => w.text)
          .join(' '),

      start:
        currentWords[0].start,

      end:
        currentWords[
          currentWords.length - 1
        ].end

    });
  }


  return chunks;
}


// ============================================
// scene 순서 정렬
// ============================================

items.sort((a, b) => {

  return (
    Number(a.json.scene_number) -
    Number(b.json.scene_number)
  );

});


let srt = '';

let subtitleIndex = 1;

// 실제 최종 scene timeline 기준
let sceneOffset = 0;


// ============================================
// SRT 생성
// ============================================

for (const item of items) {

  const json = item.json;

  const sceneNumber =
    Number(json.scene_number);


  const words =
    json.words ?? [];


  const sceneDuration =
    Number(
      json.final_scene_duration
    );


  if (
    !Array.isArray(words) ||
    words.length === 0
  ) {

    throw new Error(
      `Typecast words missing for scene ${sceneNumber}`
    );
  }


  if (
    !Number.isFinite(sceneDuration) ||
    sceneDuration <= 0
  ) {

    throw new Error(
      `Final scene duration missing for scene ${sceneNumber}`
    );
  }


  // 안전 검증
  const lastWordEnd =
    Number(
      words[
        words.length - 1
      ].end
    );


  if (
    Number.isFinite(lastWordEnd) &&
    lastWordEnd >
      sceneDuration + 0.25
  ) {

    throw new Error(
      `Scene ${sceneNumber}: speech timestamp exceeds final scene duration. ` +
      `last word=${lastWordEnd}, scene=${sceneDuration}`
    );
  }


  const chunks =
    makeChunks(words);


  for (const chunk of chunks) {

    const start =
      sceneOffset +
      chunk.start;


    const end =
      sceneOffset +
      Math.min(
        chunk.end,
        sceneDuration
      );


    srt += `${subtitleIndex}\n`;

    srt +=
      `${toSrtTime(start)} --> ${toSrtTime(end)}\n`;

    srt +=
      `${chunk.text}\n\n`;


    subtitleIndex++;
  }


  // ★ 핵심:
  // 실제 scene_N_final.mp4의 길이만 누적
  sceneOffset +=
    sceneDuration;
}


// ============================================
// OUTPUT
// ============================================

return [
  {
    json: {

      srt,

      subtitle_count:
        subtitleIndex - 1,

      total_duration:
        sceneOffset

    }
  }
];

const stdout = $input.first().json.stdout ?? '';

const lines = stdout
  .trim()
  .split('\n')
  .map(x => x.trim())
  .filter(Boolean);

return lines.map(line => {

  const [scene, duration] = line.split('|');

  const sceneNumber = Number(scene);
  const finalSceneDuration = Number(duration);

  if (
    !Number.isFinite(sceneNumber) ||
    !Number.isFinite(finalSceneDuration)
  ) {
    throw new Error(
      `Invalid scene duration line: ${line}`
    );
  }

  return {
    json: {
      scene_number: sceneNumber,
      final_scene_duration: finalSceneDuration
    }
  };
});
